-- 模型请求参数和参考素材能力。前端按 JSON 动态渲染，后端按请求参数透传。
ALTER TABLE api_models ADD COLUMN parameters JSON NULL COMMENT '模型请求参数及参考素材能力（JSON）';

INSERT INTO api_models (rfid, name, description, type, provider, parameters)
SELECT 2, 'gpt-image-2', 'gpt-image-2', 'image', 'openai', '{"version":1,"fields":[{"key":"aspect_ratio","label":"比例","type":"select","default":"1:1","options":["1:1","16:9","9:16","auto"]},{"key":"quality","label":"质量","type":"select","default":"auto","options":["low","medium","high","auto"]},{"key":"n","label":"数量","type":"number","default":1,"min":1,"max":10,"step":1},{"key":"background","label":"背景","type":"select","default":"auto","options":["auto","opaque","transparent"]},{"key":"output_format","label":"输出格式","type":"select","default":"png","options":["png","jpeg","webp"]},{"key":"output_compression","label":"压缩质量","type":"number","default":100,"min":0,"max":100,"step":1},{"key":"moderation","label":"内容审核","type":"select","default":"auto","options":["auto","low"]}],"references":{"images":{"supported":true,"max":6},"videos":{"supported":false,"max":0}}}'
WHERE NOT EXISTS (SELECT 1 FROM api_models WHERE name = 'gpt-image-2');

